if (typeof window._original_pluginSetService === 'indéfini') {
    window._original_pluginSetService = window.pluginSetService;
    window.pluginSetService = function (nom, statut, version, suffixe) {
        if (typeof window._original_pluginSetService === 'function') {
            window._original_pluginSetService (nom, statut, version, suffixe);
        }
        if (nom === 'op_waf') {
            renderWafAdditionalContent();
        }
    } ;
}

